// ── Command clauses in the JSON projection ([152d–h], stream 18) ──

fn test_def_node_to_json_command_clauses() {
	n := cx.parse_def('[?def refund-order scope=public impure [effects [write] [net]] [returns element] ($order-id::string) [refunded $order-id]]') or {
		assert false, 'parse_def failed: ${err}'
		return
	}
	got := cx.def_node_to_json(n)
	assert got.contains('"type":"DefNode"'), 'got: ${got}'
	assert got.contains('"name":"refund-order"'), 'got: ${got}'
	assert got.contains('"effects":[{"cap":"write"},{"cap":"net"}]'), 'got: ${got}'
	assert got.contains('"returns":"element"'), 'got: ${got}'
	assert got.contains('"purity":"impure"'), 'got: ${got}'
	assert got.contains('"kind":"positional","name":"order-id","type":"string"'), 'got: ${got}'
	assert !got.contains('"idempotent"'), 'no [idempotent] clause — field must be omitted; got: ${got}'
}

fn test_def_node_to_json_zero_item_effects_clause_is_present() {
	// Clause PRESENCE is the command discriminator — `[effects]` with
	// zero items still projects as an (empty) effects array.
	n := cx.parse_def('[?def touch impure [effects] ($x::string) [t $x]]') or {
		assert false, 'parse_def failed: ${err}'
		return
	}
	got := cx.def_node_to_json(n)
	assert got.contains('"effects":[]'), 'zero-item [effects] clause must project as an empty array; got: ${got}'
}

fn test_def_node_to_json_no_effects_clause_is_omitted() {
	n := cx.parse_def('[?def lookup scope=public ($id::string) [order $id]]') or {
		assert false, 'parse_def failed: ${err}'
		return
	}
	got := cx.def_node_to_json(n)
	assert !got.contains('"effects"'), 'a def with no [effects] clause must omit the field; got: ${got}'
}

fn test_def_node_to_json_idempotent_and_requires() {
	n := cx.parse_def('[?def archive impure [idempotent] [effects [write]] [requires cap:orders/archive] [returns element] ($id::string) [archived $id]]') or {
		assert false, 'parse_def failed: ${err}'
		return
	}
	got := cx.def_node_to_json(n)
	assert got.contains('"idempotent":true'), 'got: ${got}'
	assert got.contains('"requires":["cap:orders/archive"]'), 'got: ${got}'
}

