	assert got.eq(m)
	if g := got.arms[0].guard {
		assert g == '$y > 0', 'case-arm guard must round-trip'
	} else {
		assert false, 'case-arm with :where must carry guard'
	}
}

fn test_round_trip_single_when_arm() {
	m := cx.MatchNode{
