// ── Empty guard on case arm ──────────────────────────────────────────────────

fn test_round_trip_case_arm_with_empty_guard() {
	// Constructor leaves guard = none for unguarded case arms.
	m := cx.MatchNode{
		scrutinee: ?string('$v')
		arms: [
			cx.new_case_arm('1', 'one'),
			cx.new_case_arm('2', 'two'),
			cx.new_else_arm('other'),
		]
